import type { CrisisRegion } from "@/lib/types";

/**
 * Safety layer.
 *
 * Four rules hold everywhere in this app:
 *  1. Every piece of user-written text passes through `screenText` BEFORE it
 *     reaches a model, and the result travels with the response.
 *  2. Crisis resources are rendered by the app, never generated by a model.
 *     A model can time out, drift, or be rate-limited; a component cannot.
 *  3. Resources are region-aware, emergency number first. Someone in crisis in
 *     Melbourne should not have to read past two foreign numbers to reach
 *     Lifeline.
 *  4. Screening runs against EVERY language at once, never just the one the
 *     interface happens to be set to. People in distress write in whichever
 *     language the feeling arrives in — often their first, whatever the app is
 *     showing. Gating the screen on the selected locale would mean the net has
 *     a hole in it for exactly the person most likely to fall through.
 */

/* ------------------------------------------------------------- patterns
 *
 * A note on word boundaries: `\b` is defined around ASCII word characters, so
 * it does not work for Chinese (no spaces between words) or reliably for
 * Arabic. Those languages use plain substring matching instead, which is
 * slightly broader and errs toward catching too much — the right direction to
 * err in.
 */

