export const ALL_REGIONS: CrisisRegion[] = [
  "AU", "NZ", "US", "CA", "UK", "IE",
  "ES", "MX", "AR", "CO", "CL",
  "BR", "PT",
  "TW", "HK", "SG",
  "AE", "SA", "EG",
  "INTL",
];

export function crisisResources(region: CrisisRegion = "AU"): CrisisResources {
  const found = RESOURCES[region] ?? RESOURCES.INTL;
  // findahelpline is always last and always present. It is maintained by
  // people who check these numbers, which is more than this file can claim.
  return { ...found, lines: [...found.lines, FIND_A_HELPLINE] };
}

export function regionLabel(region: CrisisRegion): string {
  return (RESOURCES[region] ?? RESOURCES.INTL).label;
}

/** Regions whose numbers a human still has to confirm before launch. */
export function unverifiedRegions(): CrisisRegion[] {
  return ALL_REGIONS.filter((region) => !RESOURCES[region]?.verified);
}

/**
 * Best-effort region from the browser's IANA timezone, so the right numbers
 * show without asking. Deliberately conservative: anything unrecognised falls
 * through to the international list rather than guessing at an emergency
 * number that would not connect.
 */
export function regionFromTimeZone(timeZone: string | undefined | null): CrisisRegion {
  if (!timeZone) return "INTL";
  const zone = timeZone.toLowerCase();

  if (zone.startsWith("australia/") || zone === "antarctica/macquarie") return "AU";
  if (zone === "pacific/auckland" || zone === "pacific/chatham") return "NZ";
  if (zone === "europe/london" || zone === "europe/belfast") return "UK";
  if (zone === "europe/dublin") return "IE";
  if (zone === "europe/madrid" || zone === "africa/ceuta" || zone === "atlantic/canary") return "ES";
  if (zone === "europe/lisbon" || zone === "atlantic/madeira" || zone === "atlantic/azores") return "PT";
  if (zone === "asia/taipei") return "TW";
  if (zone === "asia/hong_kong") return "HK";
  if (zone === "asia/singapore") return "SG";
  if (zone === "asia/dubai") return "AE";
  if (zone === "asia/riyadh") return "SA";
  if (zone === "africa/cairo") return "EG";

  if (zone.startsWith("america/argentina/") || zone === "america/buenos_aires") return "AR";
  if (zone === "america/santiago" || zone === "pacific/easter") return "CL";
  if (zone === "america/bogota") return "CO";

  const MEXICO = [
    "america/mexico_city", "america/tijuana", "america/monterrey", "america/cancun",
    "america/chihuahua", "america/hermosillo", "america/mazatlan", "america/merida",
  ];
  if (MEXICO.includes(zone)) return "MX";

  const BRAZIL = [
    "america/sao_paulo", "america/bahia", "america/fortaleza", "america/recife",
    "america/manaus", "america/belem", "america/cuiaba", "america/campo_grande",
    "america/porto_velho", "america/boa_vista", "america/rio_branco", "america/maceio",
    "america/araguaina", "america/santarem", "america/noronha",
  ];
  if (BRAZIL.includes(zone)) return "BR";

  const CANADA = [
    "america/toronto", "america/vancouver", "america/edmonton", "america/winnipeg",
    "america/halifax", "america/st_johns", "america/regina", "america/moncton",
    "america/whitehorse", "america/yellowknife", "america/iqaluit",
  ];
  if (CANADA.includes(zone)) return "CA";

  if (zone.startsWith("america/") || zone.startsWith("us/") || zone === "pacific/honolulu") {
    return "US";
  }
  return "INTL";
}

